const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const nf=new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const money=value=>Number.isFinite(value)?`$${nf.format(value)}`:'—';
const DAY=86400;
const glyphs={line:'<path d="m3 17 5-7 5 4 8-11"/>',candles:'<path d="M7 2v4m0 10v6M17 2v8m0 8v4"/><rect x="4" y="6" width="6" height="10"/><rect x="14" y="10" width="6" height="8"/>',crosshair:'<path d="M12 2v5m0 10v5M2 12h5m10 0h5"/><circle cx="12" cy="12" r="4"/>',pan:'<path d="M8 12V7a2 2 0 0 1 4 0v5-7a2 2 0 0 1 4 0v7-5a2 2 0 0 1 4 0v8c0 5-3 7-7 7-3 0-5-2-7-5l-3-4a2 2 0 0 1 3-2l2 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',history:'<path d="M3 10a9 9 0 1 1 2 8M3 3v7h7"/><path d="M12 7v5l3 2"/>',book:'<path d="M12 6c-3-2-6-2-10-1v14c4-1 7-1 10 1 3-2 6-2 10-1V5c-4-1-7-1-10 1Zm0 0v14"/>',future:'<path d="m3 17 5-5 5 3 8-10M16 5h5v5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${glyphs[name]}</svg>`;
const button=(action,label,glyph)=>`<button type="button" class="eth-icon" data-equity-action="${action}" aria-label="${label}" title="${label}">${icon(glyph)}</button>`;
const COLORS={financing:'#9eaff5',governance:'#b5a5df',treasury:'#e6b66d',capital:'#9eaff5',corporate:'#9eaff5',policy:'#ce94c7',market:'#d8909e',protocol:'#7dcbbb',earnings:'#7dcbbb',claims:'#c4b2ed'};

export async function initEquityView({symbol}={}){
  const instrument=EQUITIES[symbol];if(!instrument)throw new RangeError('Unsupported equity view');
  for(const node of document.querySelectorAll('body > :not(#atlas-boot-shell):not(script)'))node.remove();
  document.body.dataset.market=symbol;document.title=`${symbol} · ${instrument.name} — Bitcoin Cycle Atlas`;
  const params=new URLSearchParams(location.search),valid=(key,values,fallback)=>values.includes(params.get(key))?params.get(key):fallback;
  const state={frequency:valid('granularity',['daily','weekly'],'daily'),chartType:valid('type',['line','candles'],'line'),scale:valid('axis',['linear','log'],'log'),span:valid('equity-span',['1m','6m','1y','4y','all'],'4y'),scenario:valid('treasury-scenario',['stress','base','bull'],'base'),forecastVisible:params.get('forecast')!=='off',eventsVisible:params.get('events')!=='off',category:'all',selectedEvent:null,tool:'crosshair',range:null,priceDomain:null,controller:null,selectedTime:null,frame:null,loading:false,error:null};
  const events=TREASURY_EVENTS.filter(event=>event.symbol===symbol);
  let daily=null,weekly=null,forecast=null,forecastError=null,request=null,generation=0;
  const app=document.createElement('main');app.id='main';app.className='eth-app equity-app';app.dataset.bootContent='';app.inert=true;app.setAttribute('aria-hidden','true');
  app.innerHTML=`<nav class="eth-tools" aria-label="차트 조작 도구"><span class="equity-brand" aria-hidden="true">${symbol==='MSTR'?'M':'B'}</span>${button('crosshair','십자선 · C','crosshair')}${button('pan','차트 이동 · H','pan')}<span class="eth-rail-unit">USD / SHARE</span></nav>
    <header class="eth-topbar"><button id="equity-symbol" class="workbench-symbol" type="button">${symbol}</button><div class="equity-intervals" role="group" aria-label="주식 봉 간격">${EQUITY_INTERVALS.map(item=>`<button type="button" data-equity-interval="${item.id}" title="뉴욕 거래 세션 ${item.label}">${item.label}</button>`).join('')}</div><span class="eth-divider" aria-hidden="true"></span><div class="eth-chart-types" role="group" aria-label="차트 유형">${button('line','가격선','line')}${button('candles','실제 OHLC 캔들','candles')}</div><select id="equity-scenario" aria-label="조건부 전망 시나리오"><option value="stress">스트레스</option><option value="base">기준 가정</option><option value="bull">채택 확대</option></select><span class="eth-top-spacer"></span>${button('forecast','미래 전망과 근거','future')}${button('history','역사 사건','history')}${button('research','리서치 읽기 순서','book')}${button('info','가격 자료와 계산 출처','info')}</header>
    <section class="atlas-plot eth-plot equity-plot" aria-label="${instrument.koreanName} 실제 가격과 조건부 미래 전망"><svg id="equity-chart" role="group" tabindex="0" aria-label="${symbol} 가격 차트. 실선과 캔들은 관측, 점선과 음영은 조건부 미래 가정입니다."></svg><div class="eth-readout"><div class="eth-readout-heading"><strong>${instrument.name} / USD</strong><span id="equity-readout-interval"></span><span class="eth-venue">${instrument.exchange.toUpperCase()} · 분할 조정</span></div><div class="eth-readout-value"><strong id="equity-price">—</strong><span id="equity-change"></span><time id="equity-bar-time"></time><span id="equity-kind"></span></div><div id="equity-ohlc" class="eth-ohlc"></div></div><div class="equity-legend"><span>— 실제 관측</span><span class="equity-projected">┄ 조건부 전망 · 근거 ○</span><span id="equity-vintage"></span></div><div id="equity-empty" class="eth-empty" role="status"><p id="equity-empty-message">${symbol} 가격 자료를 불러오고 있습니다.</p><button type="button" data-equity-action="reload" hidden>다시 조회</button></div><button type="button" id="equity-touch-hint" class="chart-touch-tracking-hint" hidden>값 추적 중 · 탭하여 종료</button></section>
    <footer class="eth-bottom"><div class="eth-periods" role="group" aria-label="표시 기간">${[['1m','1개월'],['6m','6개월'],['1y','1년'],['4y','4년'],['all','전체']].map(([id,label])=>`<button type="button" data-equity-span="${id}">${label}</button>`).join('')}</div><select id="equity-period-select" aria-label="표시 기간">${[['1m','1개월'],['6m','6개월'],['1y','1년'],['4y','4년'],['all','전체']].map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select><span id="equity-status" role="status" aria-live="polite"></span><span class="eth-timezone">뉴욕 세션</span><button type="button" data-equity-action="scale">로그</button><button type="button" data-equity-action="auto">Auto</button></footer><span id="equity-announcement" class="lab-visually-hidden" role="status" aria-live="polite"></span>`;
  document.body.append(app);
  const $=selector=>app.querySelector(selector),$$=selector=>[...app.querySelectorAll(selector)],svg=$('#equity-chart'),plot=$('.equity-plot');
  const selector=mountSymbolSelector({button:$('#equity-symbol'),symbol});
  const dialog=document.createElement('dialog');dialog.id='equity-detail-dialog';dialog.className='eth-data-dialog equity-detail-dialog';dialog.setAttribute('aria-labelledby','equity-detail-title');dialog.innerHTML=`<header><h2 id="equity-detail-title"></h2><button type="button" aria-label="닫기">${icon('close')}</button></header><div id="equity-detail-content"></div>`;document.body.append(dialog);
  const viewport=mountDialogViewport(dialog);let dialogOpener=null;
  const close=()=>dialog.close();dialog.querySelector('header button').onclick=close;
  dialog.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))(dialogOpener?.isConnected?dialogOpener:$('#equity-symbol')).focus({preventScroll:true});});
  dialog.addEventListener('click',event=>{if(event.target===dialog){const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)close();}const source=event.target.closest('[data-equity-source]');if(source){close();openResearchArticle(source.dataset.equitySource,{opener:dialogOpener});}const jump=event.target.closest('[data-equity-event-jump]');if(jump){focusEvent(jump.dataset.equityEventJump);close();}const eventButton=event.target.closest('[data-equity-event]');if(eventButton)showEvent(eventButton.dataset.equityEvent);});
  dialog.addEventListener('change',event=>{if(event.target.id==='equity-history-visible'){state.eventsVisible=event.target.checked;persist();schedule();}if(event.target.id==='equity-history-category'){state.category=event.target.value;showHistory();schedule();}});
  dialog.addEventListener('keydown',event=>{event.stopPropagation();});
  const current=()=>state.frequency==='weekly'?weekly:daily;
  const announce=text=>{$('#equity-announcement').textContent=text;};
  const touch=mountChartTouchTracking({element:plot,getTool:()=>state.tool,canStart:point=>{const box=svg.getBoundingClientRect(),view=svg.viewBox.baseVal,x=(point.clientX-box.left)/box.width*view.width,y=(point.clientY-box.top)/box.height*view.height;return Boolean(state.controller)&&x>=Number(svg.dataset.plotLeft)&&x<=Number(svg.dataset.plotRight)&&y>=Number(svg.dataset.plotTop)&&y<=Number(svg.dataset.priceBottom);},preview:point=>state.controller?.previewPointer?.(point),clear:()=>state.controller?.clearPreview?.(),cancelNavigation:()=>navigation.cancelGesture(),resumeNavigation:points=>navigation.resumeTouchGesture(points),onChange:active=>{$('#equity-touch-hint').hidden=!active;}});
  $('#equity-touch-hint').onclick=()=>touch.cancel();
  const navigation=bindChartNavigation({element:plot,getRange:()=>state.range,getTool:()=>state.tool,getPriceAxis:()=>state.controller?.getPriceScale?.(),getContext:context=>state.controller?.getSelection?.(context),onGestureStart:()=>touch.cancelPending(),onMenuOpen:()=>touch.cancel(),onRangeChange:range=>{state.range=range;schedule();},onPriceRangeChange:domain=>{state.priceDomain=domain;schedule();},onPriceReset:()=>{state.priceDomain=null;schedule();},onReset:()=>{cancelInteraction();state.range=null;state.priceDomain=null;state.span='4y';persist();schedule();},onAnnounce:announce});
  function cancelInteraction(){touch.cancel();navigation.cancelGesture();clearChartHover(svg);state.selectedTime=null;}
  function persist(){const query=new URLSearchParams({symbol});if(state.frequency!=='daily')query.set('granularity',state.frequency);if(state.chartType==='candles')query.set('type','candles');if(state.scale==='linear')query.set('axis','linear');if(state.span!=='4y')query.set('equity-span',state.span);if(state.scenario!=='base')query.set('treasury-scenario',state.scenario);if(!state.forecastVisible)query.set('forecast','off');if(!state.eventsVisible)query.set('events','off');try{history.replaceState(null,'',`${location.pathname}?${query}`);}catch{}}
  function openDialog(title,markup){cancelInteraction();if(!dialog.open)dialogOpener=document.activeElement;document.dispatchEvent(new CustomEvent('atlas:modal-open',{detail:{id:dialog.id}}));dialog.querySelector('h2').textContent=title;dialog.querySelector('#equity-detail-content').innerHTML=markup;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
  function sourceLinks(ids=[]){return `<div class="equity-source-links">${ids.map(id=>{const source=getResearchArticle(id)||TREASURY_SOURCES.find(item=>item.id===id);return source?`<button type="button" data-equity-source="${esc(id)}">${esc(source.title)} ↗</button>`:'';}).join('')}</div>`;}
  function showResearch(){
    const sources=TREASURY_SOURCES.filter(item=>(item.symbols||item.assets||[]).includes(symbol)||item.symbol===symbol);
    const categories=['filing','data','method','leadership','risk'];
    const groups=categories.map(category=>{const ids=sources.filter(item=>item.category===category).map(item=>item.id);return ids.length?`<h3>${esc(RESEARCH_CATEGORIES[category])}</h3>${sourceLinks(ids)}`:'';}).join('');
    const extra=sources.filter(item=>!categories.includes(item.category));
    openDialog(`${symbol} 리서치 읽기 순서`,`<p>공시와 가격 원자료 → 경영진 주장 → 수학적 가정과 반대 근거 순으로 읽습니다.</p><p><a href="${esc(location.pathname)}?page=evidence&amp;research-asset=${symbol}">전체 리서치 읽기 순서 ↗</a></p>${groups}${extra.length?`<h3>관련 기록</h3>${sourceLinks(extra.map(item=>item.id))}`:''}`);
  }
  function showHistory(){const shown=events.filter(item=>state.category==='all'||item.category===state.category),categories=[...new Set(events.map(item=>item.category))];openDialog(`${symbol} 역사 사건`,`<div class="equity-history-controls"><label><input id="equity-history-visible" type="checkbox" ${state.eventsVisible?'checked':''}> 차트에 표시</label><select id="equity-history-category" aria-label="사건 분류"><option value="all">전체 분류</option>${categories.map(id=>`<option value="${esc(id)}" ${state.category===id?'selected':''}>${esc(id)}</option>`).join('')}</select></div><p>사건 기록과 같은 시기 가격의 움직임을 연결해 볼 수 있습니다. 특정 사건이 가격 변화를 단독으로 일으켰다는 뜻은 아닙니다.</p><div class="equity-events-list">${[...shown].reverse().map(event=>`<button type="button" data-equity-event="${esc(event.id)}"><time>${esc(event.date)}</time><strong>${esc(event.title)}</strong></button>`).join('')}</div>`);}
  function showEvent(id){const event=events.find(item=>item.id===id);if(!event)return;state.selectedEvent=id;const covered=daily&&event.date>=daily.firstDate.slice(0,10)&&event.date<=daily.lastDate.slice(0,10);openDialog(event.title,`${treasuryEventMarkup(event)}<p>${covered?'표식의 높이는 주변 거래 세션의 종가입니다. 사건 발생 순간의 체결 가격이 아닙니다.':'현재 가격 자료 범위 밖 사건입니다. 가격을 만들어 표시하지 않습니다.'}</p><button type="button" data-equity-event-jump="${esc(id)}" ${covered?'':'disabled'}>차트에서 보기</button>${sourceLinks(event.sourceIds)}`);schedule();}
  function focusEvent(id){const event=events.find(item=>item.id===id);if(!event||!daily)return;const time=Date.parse(`${event.date}T00:00:00Z`)/1000;if(time<daily.candles[0].time||time>daily.candles.at(-1).time)return;state.frequency='daily';state.eventsVisible=true;state.selectedEvent=id;state.priceDomain=null;const range=equityHistoryRange(daily,{span:'4y',forecastEnd:forecast?.path.at(-1)?.date});state.range={...range,start:time-90*DAY,end:time+120*DAY};persist();schedule();}
  function showForecast(id=null){
    const milestone=forecast?.milestones.find(item=>item.id===id);
    if(!forecast){openDialog(`${symbol} 전망`, `<p>${esc(forecastError||'자료가 준비되면 조건부 전망을 계산합니다.')}</p>`);return;}
    const assumptions=forecast.assumptions||{},coin=forecast.snapshot.coin||'기초 코인';
    const comparisons=['stress','base','bull'].map(scenario=>scenario===state.scenario?forecast:buildTreasuryForecast({symbol,history:daily.candles,scenario,asOf:forecast.asOf,endYear:Number(forecast.displayEnd.slice(0,4))}));
    const quantity=value=>Number.isFinite(value)?value.toLocaleString('en-US',{maximumFractionDigits:2}):'—';
    const funding=value=>Number.isFinite(value)?value>=1e9?`$${nf.format(value/1e9)}B`:value>=1e6?`$${nf.format(value/1e6)}M`:money(value):'—';
    const bullEnd=comparisons.find(item=>item.scenario.id==='bull').path.at(-1);
    const comparison=`<h3>가격 가정에 필요한 자금과 희석</h3><p><strong>채택 확대 조건은 ${esc(bullEnd.date)}까지 누적 순조달 ${esc(funding(bullEnd.components.capitalRaised))}를 전제합니다.</strong> 아래 가격과 보유량은 해당 규모의 신규 자금과 주식 발행이 가능하다는 조건에 의존합니다.</p><p>누적 순조달은 가격 기준일 이후 해당 날짜까지 발행 비용을 뺀 보통주 발행대금입니다. 확보된 자금이나 회사의 확정 조달 계획이 아닙니다. 보통주 수에는 발행과 무상 희석이 모두 포함됩니다. B = 10억 달러 · M = 100만 달러. 작은 화면에서는 표를 가로로 움직여 세 조건을 비교할 수 있습니다.</p>${['2030-12-31',forecast.displayEnd].filter((date,index,dates)=>date>forecast.asOf&&dates.indexOf(date)===index).map(date=>{
      const points=comparisons.map(item=>item.path.find(row=>row.date===date));
      const rows=[['주당 가격 가정',row=>money(row.price)],['누적 순조달',row=>funding(row.components.capitalRaised)],['보통주 수',row=>`${quantity(row.components.shares)}주`],[`${coin} 보유량`,row=>`${quantity(row.components.coinUnits)} ${coin}`]];
      return `<div role="region" tabindex="0" aria-label="${date} 시나리오 비교" style="overflow-x:auto;margin:16px 0"><table data-equity-comparison-year="${date.slice(0,4)}" style="width:100%;border-collapse:collapse;font-size:11px;line-height:1.7;text-align:right"><caption style="text-align:left;color:#d0deee;padding:6px 0;font-weight:600">${date} · 조건별 계산</caption><thead><tr><th scope="col" style="padding:9px 6px;text-align:left;border-bottom:1px solid #34465e">계산 항목</th>${comparisons.map(item=>`<th scope="col" style="padding:9px 6px;border-bottom:1px solid #34465e;white-space:nowrap">${esc(item.scenario.label)}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,format])=>`<tr><th scope="row" style="padding:9px 6px;text-align:left;border-bottom:1px solid #28384c;white-space:nowrap">${esc(label)}</th>${points.map(row=>`<td style="padding:9px 6px;border-bottom:1px solid #28384c;white-space:nowrap">${esc(row?format(row):'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
    }).join('')}`;
    const inputRows=[['선택한 조건',forecast.scenario?.label||state.scenario],['재무 기준일',forecast.financialAsOf||forecast.snapshot.asOf],['가격 기준일',forecast.asOf],['코인 관측 기준',`${forecast.coinAnchor?.date||'—'} · ${money(forecast.coinAnchor?.price)}`],['보유 코인',`${(forecast.snapshot.coinUnits||0).toLocaleString('en-US')} ${coin}`],['보통주 수',`${(forecast.snapshot.shares||0).toLocaleString('en-US')}주`],...(assumptions.anchors||[]).map(item=>[`${coin} ${item.date} 조건`,money(item.price)])];
    openDialog(milestone?.title||`${symbol} 조건부 전망과 근거`,`<p class="eth-data-lead">${esc(milestone?.description||'보유 코인·선순위 청구권·주식 수·프리미엄을 분리한 조건부 계산입니다.')}</p><p class="equity-vintage-note">${esc(forecast.warnings?.[0]||'재무 공시와 가격 관측의 기준일을 확인해 주세요.')}</p>${comparison}<h3>선택한 조건의 입력 자료</h3><dl>${inputRows.map(([label,value])=>`<dt>${esc(label)}</dt><dd>${esc(value)}</dd>`).join('')}</dl><h3>계산하는 방법</h3><div class="equity-formula">주가 가정 = 시장 프리미엄 × 보통주에 남는 순자산 ÷ 주식 수<br>남는 순자산 = 코인 가치 + 현금 + 기타 자산 − 부채 − 우선주 − 기타 청구권</div><h3>명시한 조건</h3><ul>${(assumptions.labels||[]).map(label=>`<li>${esc(label)}</li>`).join('')}</ul><h3>해석 범위</h3><ul>${(forecast.warnings||[]).slice(1).map(item=>`<li>${esc(typeof item==='string'?item:item.message||'모델 기준 확인 필요')}</li>`).join('')}</ul>${sourceLinks([...new Set([...(milestone?.sourceIds||[]),...comparisons.flatMap(item=>item.path.flatMap(row=>row.sourceIds||[]))])])}<label class="equity-forecast-switch"><input id="equity-forecast-visible" type="checkbox" ${state.forecastVisible?'checked':''}> 차트에 미래 가정 표시</label>`);
    dialog.querySelector('#equity-forecast-visible').onchange=event=>{state.forecastVisible=event.target.checked;state.range=null;persist();schedule();};
  }
  function showInfo(){const series=current();openDialog(`${symbol} 가격 자료`,series?`<p class="eth-data-lead">${instrument.name} · ${instrument.exchange}<strong>${symbol} · USD / share</strong></p><dl><dt>관측 범위</dt><dd>${daily.firstDate.slice(0,10)} – ${daily.lastDate.slice(0,10)}</dd><dt>일별 세션</dt><dd>${daily.candles.length.toLocaleString('en-US')}개</dd><dt>수집 시각</dt><dd>${esc(daily.retrievedAt)}</dd><dt>가격 제공자</dt><dd>Yahoo Finance</dd>${daily.validation?`<dt>독립 교차 확인</dt><dd>Nasdaq 최근 ${daily.validation.comparedSessions}세션 · OHLC 최대 차이 $${Number(daily.validation.maxOHLCPriceDifference).toFixed(4)} · 거래량 차이는 보존</dd>`:''}<dt>가격·주식 단위</dt><dd>제공자 분할 조정 OHLC. 배당 조정 종가를 캔들로 합성하지 않습니다.</dd><dt>시간 기준</dt><dd>America/New_York 거래 세션일</dd></dl><p>${esc(instrument.historyNote)}</p><p>일봉은 완료된 미국 거래 세션만 표시합니다. 주봉은 실제 세션을 모아 집계하며 휴장일에 가격을 채우지 않습니다. 분·시간봉은 이 주식 자료에서 제공하지 않습니다. 일별 선은 인접 관측을 연결합니다.</p>${daily.validation?`<p>${esc(daily.validation.note)} <a href="${esc(daily.validation.sourceUrl)}" target="_blank" rel="noopener noreferrer">Nasdaq 대조 자료 ↗</a></p>`:''}<p>주식 분할에 따라 과거 수치가 다시 조정될 수 있습니다. 미래 곡선에는 OHLC·거래량을 만들지 않습니다.</p><a href="${esc(daily.sourcePage)}" target="_blank" rel="noopener noreferrer">가격 원자료 ↗</a>`:'<p>가격 자료를 불러오는 중입니다.</p>');}
  function readout(row){$('#equity-price').textContent=money(row.price??row.close);$('#equity-bar-time').textContent=(row.date||'').slice(0,10);$('#equity-kind').textContent=row.kind==='forecast'?(row.interpolated?'조건부 가정 · 보간':'조건부 가정'):'';const change=row.kind==='forecast'?null:row.changePct;$('#equity-change').textContent=Number.isFinite(change)?`${change>=0?'+':'−'}${nf.format(Math.abs(change))}%`:'';$('#equity-change').className=change<0?'eth-loss':'eth-gain';$('#equity-ohlc').innerHTML=row.kind==='forecast'?`<span>가정 범위 ${row.interpolation?.unavailableBounds?.length?'로그축 0 경계 · 선형축에서 확인':`${money(row.low)} – ${money(row.high)}`}</span><span>원형 표식 → 계산 근거</span>`:row.kind==='unavailable'?'이 구간에 관측 또는 가정 값이 없습니다.':[['O',row.open],['H',row.high],['L',row.low],['C',row.close]].map(([label,value])=>`<span><i>${label}</i> ${money(value)}</span>`).join('');if(!row.hovered)state.selectedTime=row.time;}
  function calculate(){forecastError=null;try{forecast=buildTreasuryForecast({symbol,history:daily.candles,scenario:state.scenario,endYear:2035});}catch(error){forecast=null;forecastError=error.message;console.error('Equity scenario unavailable',error);}}
  function render(){state.frame=null;const series=current();$('#equity-empty').hidden=Boolean(series);$('.eth-readout').hidden=!series;$('#equity-empty-message').textContent=state.error?`${symbol} 저장 가격 자료를 불러오지 못했습니다. 다시 조회해 주세요.`:`${symbol} 가격 자료를 불러오고 있습니다.`;$('#equity-empty button').hidden=!state.error;if(!series){svg.innerHTML='';state.controller=null;$('#equity-status').textContent=state.error?'조회 실패':'불러오는 중';return;}
    $('#equity-scenario').value=state.scenario;$('#equity-readout-interval').textContent=state.frequency==='daily'?'· 1D':'· 1W';for(const item of $$('[data-equity-interval]'))item.setAttribute('aria-pressed',String(item.dataset.equityInterval===state.frequency));for(const item of $$('[data-equity-action]'))if(['line','candles','crosshair','pan'].includes(item.dataset.equityAction))item.setAttribute('aria-pressed',String(item.dataset.equityAction===state.tool||item.dataset.equityAction===state.chartType));for(const item of $$('[data-equity-span]'))item.setAttribute('aria-pressed',String(item.dataset.equitySpan===state.span));$('#equity-period-select').value=state.span;$('[data-equity-action="scale"]').textContent=state.scale==='log'?'로그':'선형';$('[data-equity-action="auto"]').setAttribute('aria-pressed',String(!state.priceDomain));$('[data-equity-action="forecast"]').setAttribute('aria-pressed',String(state.forecastVisible));$('.equity-projected').hidden=!state.forecastVisible;$('#equity-vintage').textContent=state.forecastVisible&&forecast?`재무 ${forecast.financialAsOf} · 과거 구조 가정`:'';$('#equity-vintage').title=forecast?.warnings?.[0]||'';
    if(!state.range)state.range=equityHistoryRange(series,{span:state.span,forecastEnd:state.forecastVisible?forecast?.path.at(-1)?.date:null});
    state.controller=drawIntradayChart({svg,series,range:state.range,chartType:state.chartType,scale:state.scale,priceDomain:state.priceDomain,showVolume:false,tool:state.tool,selectedTime:state.selectedTime,headerInset:plot.clientHeight<300?55:88,onHover:readout,forecast:state.forecastVisible?forecast:null,onForecastEvidence:showForecast,historicalEvents:events.filter(item=>state.category==='all'||item.category===state.category),showHistoricalEvents:state.eventsVisible,activeHistoricalEventId:state.selectedEvent,historicalEventColors:COLORS,onHistoricalEvent:showEvent});
    $('#equity-status').textContent=`${daily.lastDate.slice(0,10)}${forecastError?' · 전망 입력 확인 필요':''}`;$('#equity-status').title=`Yahoo Finance · 마지막 저장 세션 ${daily.lastDate.slice(0,10)} · ${daily.retrievedAt} 수집`;plot.dataset.tool=state.tool;navigation.update();}
  function schedule(){if(state.frame===null)state.frame=requestAnimationFrame(render);}
  async function load(){if(state.loading)return;const token=++generation;state.loading=true;state.error=null;request=new AbortController();schedule();try{const embedded=document.getElementById(`embedded-${symbol.toLowerCase()}-data`)?.textContent;let payload;if(embedded)payload=JSON.parse(embedded);else{const response=await fetch(`./data/${symbol.toLowerCase()}-ohlc.json`,{credentials:'omit',cache:'no-cache',signal:AbortSignal.any([request.signal,AbortSignal.timeout(20000)])});if(!response.ok)throw new Error(`Price archive HTTP ${response.status}`);payload=await response.json();}const nextDaily=parseEquityArchive(payload,{symbol}),nextWeekly=parseEquityArchive(payload,{symbol,interval:'weekly'});if(token!==generation)return;daily=nextDaily;weekly=nextWeekly;calculate();}catch(error){if(token===generation&&error.name!=='AbortError')state.error=error.message;}finally{if(token===generation){state.loading=false;schedule();}}}
  function changeSpan(span){cancelInteraction();state.span=span;state.range=null;state.priceDomain=null;persist();schedule();}
  app.addEventListener('click',event=>{const interval=event.target.closest('[data-equity-interval]');if(interval){cancelInteraction();state.frequency=interval.dataset.equityInterval;state.range=null;state.priceDomain=null;persist();schedule();return;}const span=event.target.closest('[data-equity-span]');if(span){changeSpan(span.dataset.equitySpan);return;}const action=event.target.closest('[data-equity-action]')?.dataset.equityAction;if(!action)return;if(action==='reload'){void load();return;}if(action==='info'){showInfo();return;}if(action==='history'){showHistory();return;}if(action==='research'){showResearch();return;}if(action==='forecast'){showForecast();return;}cancelInteraction();if(['line','candles'].includes(action))state.chartType=action;if(['crosshair','pan'].includes(action))state.tool=action;if(action==='scale'){state.scale=state.scale==='log'?'linear':'log';state.priceDomain=null;}if(action==='auto')state.priceDomain=null;persist();schedule();});
  $('#equity-scenario').onchange=event=>{cancelInteraction();state.scenario=event.target.value;state.priceDomain=null;if(daily)calculate();persist();schedule();};$('#equity-period-select').onchange=event=>changeSpan(event.target.value);
  const onModal=event=>{cancelInteraction();if(event.detail?.id!==dialog.id&&dialog.open)dialog.close();};document.addEventListener('atlas:modal-open',onModal);
  const onKey=event=>{if(event.ctrlKey||event.metaKey||event.altKey||event.isComposing||event.target.closest('input,select,textarea,dialog,[contenteditable="true"]'))return;const action={c:'crosshair',h:'pan'}[event.key.toLowerCase()];if(action){event.preventDefault();$(`[data-equity-action="${action}"]`).click();}};document.addEventListener('keydown',onKey);
  const observer=new ResizeObserver(schedule);observer.observe(plot);document.fonts?.ready.then(schedule);
  window.addEventListener('pagehide',event=>{++generation;request?.abort();state.loading=false;if(state.frame!==null){cancelAnimationFrame(state.frame);state.frame=null;}cancelInteraction();if(!event.persisted){touch.destroy();navigation.destroy();observer.disconnect();selector.destroy();viewport.destroy();document.removeEventListener('atlas:modal-open',onModal);document.removeEventListener('keydown',onKey);}});
  window.addEventListener('pageshow',event=>{if(event.persisted){if(!daily)void load();else schedule();}});
  persist();await load();await new Promise(resolve=>requestAnimationFrame(()=>{render();resolve();}));document.dispatchEvent(new CustomEvent('atlas:ready'));const article=params.get('article');if(article&&getResearchArticle(article))openResearchArticle(article,{opener:$('#equity-symbol'),view:params.get('article-view')});
}
